<?php
require_once __DIR__.'/includes/functions.php';require_customer();verify_csrf();$uid=(int)current_user()['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){$pid=(int)($_POST['product_id']??0);$action=$_POST['action']??'';
if($action==='add'){$qty=max(1,min(99,(int)($_POST['quantity']??1)));$s=$conn->prepare('SELECT stock,is_active FROM products WHERE id=?');$s->bind_param('i',$pid);$s->execute();$p=$s->get_result()->fetch_assoc();if($p&&$p['is_active']&&(int)$p['stock']>0){$qty=min($qty,(int)$p['stock']);$s=$conn->prepare('INSERT INTO cart_items(user_id,product_id,quantity) VALUES(?,?,?) ON DUPLICATE KEY UPDATE quantity=LEAST(quantity+VALUES(quantity),?)');$s->bind_param('iiii',$uid,$pid,$qty,$p['stock']);$s->execute();flash('Product added to your cart.');}else flash('This product is not currently available.','error');}
elseif($action==='update'){foreach(($_POST['qty']??[]) as $id=>$q){$id=(int)$id;$q=max(0,min(99,(int)$q));if($q===0){$s=$conn->prepare('DELETE FROM cart_items WHERE user_id=? AND product_id=?');$s->bind_param('ii',$uid,$id);}else{$s=$conn->prepare('UPDATE cart_items c JOIN products p ON p.id=c.product_id SET c.quantity=LEAST(?,p.stock) WHERE c.user_id=? AND c.product_id=? AND p.stock>0');$s->bind_param('iii',$q,$uid,$id);} $s->execute();}flash('Cart updated.');}
elseif($action==='remove'){$s=$conn->prepare('DELETE FROM cart_items WHERE user_id=? AND product_id=?');$s->bind_param('ii',$uid,$pid);$s->execute();flash('Product removed from cart.');}
redirect('cart.php');}
$items=get_cart_items($conn,$uid);$subtotal=cart_subtotal($items);$delivery=delivery_charge($subtotal);render_header('Your cart');?>
<div class="page-heading"><span class="eyebrow">YOUR SELECTION</span><h1>Shopping cart</h1><p class="muted">Review your items before checkout.</p></div>
<?php if(!$items):?><div class="empty-state"><div class="empty-icon">🛒</div><h2>Your cart is waiting to be filled</h2><p>Explore our everyday essentials and add your favourites.</p><a class="button" href="<?=e(url())?>">Continue shopping</a></div><?php else:?><div class="cart-layout"><form class="cart-list" method="post"><?=csrf_field()?><input type="hidden" name="action" value="update"><?php foreach($items as $i):?><div class="cart-item"><img src="<?=e(image_path($i['image']))?>" alt=""><div class="cart-item-main"><b><?=e($i['name'])?></b><small><?=money($i['price'])?> each · <?=$i['stock']?> in stock</small><label>Qty <input type="number" name="qty[<?=$i['product_id']?>]" min="0" max="<?=$i['stock']?>" value="<?=$i['quantity']?>"></label></div><strong><?=money((float)$i['price']*(int)$i['quantity'])?></strong><button class="text-button" form="remove-<?=$i['product_id']?>">Remove</button></div><?php endforeach;?><button class="button secondary">Update cart</button></form><aside class="summary-card"><h2>Order summary</h2><div><span>Subtotal</span><b><?=money($subtotal)?></b></div><div><span>Delivery</span><b><?=money($delivery)?></b></div><hr><div class="summary-total"><span>Total</span><b><?=money($subtotal+$delivery)?></b></div><a class="button full" href="<?=e(url('checkout.php'))?>">Proceed to checkout</a><p class="muted tiny">Delivery is available only to active PIN codes.</p></aside></div><?php foreach($items as $i):?><form id="remove-<?=$i['product_id']?>" method="post"><?=csrf_field()?><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?=$i['product_id']?>"></form><?php endforeach;endif;render_footer();?>
